        "viz_card_02_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Reports the failed share of selected-window remote-access VPN connection attempts. Stacked columns preserve successful and failed attempt volume over time."
            }
        },
        "viz_card_02_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
